    summary: ["Ringkasan pesanan", "Order summary", "\u0421\u043E\u0441\u0442\u0430\u0432 \u0437\u0430\u043A\u0430\u0437\u0430", "Buyurtma tarkibi"],
    total: ["Total pembayaran", "Total payment", "\u0418\u0442\u043E\u0433\u043E \u043A \u043E\u043F\u043B\u0430\u0442\u0435", "Jami to\u2018lov"],
    noRecurring: ["Pembayaran sekali. Tidak diperpanjang otomatis.", "One-time payment. No automatic renewal.", "\u0420\u0430\u0437\u043E\u0432\u0430\u044F \u043E\u043F\u043B\u0430\u0442\u0430. \u0411\u0435\u0437 \u0430\u0432\u0442\u043E\u043F\u0440\u043E\u0434\u043B\u0435\u043D\u0438\u044F.", "Bir martalik to\u2018lov. Avtomatik uzaytirilmaydi."],
