    "employers.feature1": { en: "Publish and manage jobs", ru: "\u041F\u0443\u0431\u043B\u0438\u043A\u0443\u0439\u0442\u0435 \u0432\u0430\u043A\u0430\u043D\u0441\u0438\u0438 \u0438 \u0443\u043F\u0440\u0430\u0432\u043B\u044F\u0439\u0442\u0435 \u0438\u043C\u0438", uz: "Vakansiyalarni e\u2019lon qiling va boshqaring" },
    "employers.feature1Sub": { en: "Create roles, update details, and reach the right candidates.", ru: "\u0421\u043E\u0437\u0434\u0430\u0432\u0430\u0439\u0442\u0435 \u0432\u0430\u043A\u0430\u043D\u0441\u0438\u0438, \u043E\u0431\u043D\u043E\u0432\u043B\u044F\u0439\u0442\u0435 \u0434\u0435\u0442\u0430\u043B\u0438 \u0438 \u043D\u0430\u0445\u043E\u0434\u0438\u0442\u0435 \u043D\u0443\u0436\u043D\u044B\u0445 \u043A\u0430\u043D\u0434\u0438\u0434\u0430\u0442\u043E\u0432.", uz: "Vakansiya yarating, ma\u2019lumotlarni yangilang va mos nomzodlarni toping." },
    "employers.feature2": { en: "Review candidate profiles", ru: "\u0418\u0437\u0443\u0447\u0430\u0439\u0442\u0435 \u043F\u0440\u043E\u0444\u0438\u043B\u0438 \u043A\u0430\u043D\u0434\u0438\u0434\u0430\u0442\u043E\u0432", uz: "Nomzodlarning profilini ko\u2018rib chiqing" },
