    "employers.feature3": { en: "Organize your hiring pipeline", ru: "\u041E\u0440\u0433\u0430\u043D\u0438\u0437\u0443\u0439\u0442\u0435 \u044D\u0442\u0430\u043F\u044B \u043D\u0430\u0439\u043C\u0430", uz: "Yollash bosqichlarini tartibga soling" },
    "employers.feature3Sub": { en: "Track progress from application to hire.", ru: "\u0421\u043B\u0435\u0434\u0438\u0442\u0435 \u0437\u0430 \u043F\u0440\u043E\u0433\u0440\u0435\u0441\u0441\u043E\u043C \u043E\u0442 \u043E\u0442\u043A\u043B\u0438\u043A\u0430 \u0434\u043E \u043D\u0430\u0439\u043C\u0430.", uz: "Arizadan ishga qabul qilishgacha jarayonni kuzating." },
