    "rw.noCompany": { en: "No company workspace is available", ru: "\u041D\u0435\u0442 \u0434\u043E\u0441\u0442\u0443\u043F\u043D\u043E\u0439 \u043A\u043E\u043C\u043F\u0430\u043D\u0438\u0438", uz: "Kompaniya ish maydoni mavjud emas" },
    "rw.noCompanyHint": { en: "Use an employer account with a company or accept a company invitation.", ru: "\u0412\u043E\u0439\u0434\u0438\u0442\u0435 \u0432 \u0430\u043A\u043A\u0430\u0443\u043D\u0442 \u0441 \u043A\u043E\u043C\u043F\u0430\u043D\u0438\u0435\u0439 \u0438\u043B\u0438 \u043F\u0440\u0438\u043C\u0438\u0442\u0435 \u043F\u0440\u0438\u0433\u043B\u0430\u0448\u0435\u043D\u0438\u0435.", uz: "Kompaniyali akkauntdan foydalaning yoki taklifni qabul qiling." },
