    "li.integrations": { en: "Integrations", ru: "\u0418\u043D\u0442\u0435\u0433\u0440\u0430\u0446\u0438\u0438", uz: "Integratsiyalar" },
    "li.settingsTitle": { en: "LinkedIn profile sharing", ru: "\u041F\u0443\u0431\u043B\u0438\u043A\u0430\u0446\u0438\u044F \u0432 LinkedIn", uz: "LinkedIn profilida ulashish" },
    "li.settingsHint": { en: "Connect your personal LinkedIn profile to share selected job posts from your own feed.", ru: "\u041F\u043E\u0434\u043A\u043B\u044E\u0447\u0438\u0442\u0435 \u043B\u0438\u0447\u043D\u044B\u0439 \u043F\u0440\u043E\u0444\u0438\u043B\u044C LinkedIn, \u0447\u0442\u043E\u0431\u044B \u043F\u0443\u0431\u043B\u0438\u043A\u043E\u0432\u0430\u0442\u044C \u0432\u044B\u0431\u0440\u0430\u043D\u043D\u044B\u0435 \u0432\u0430\u043A\u0430\u043D\u0441\u0438\u0438 \u0432 \u0441\u0432\u043E\u0435\u0439 \u043B\u0435\u043D\u0442\u0435.", uz: "Tanlangan vakansiyalarni o\u2018z LinkedIn profilingizda ulashish uchun shaxsiy profilingizni ulang." },
    "li.personalProfile": { en: "Personal HR profile", ru: "\u041B\u0438\u0447\u043D\u044B\u0439 \u043F\u0440\u043E\u0444\u0438\u043B\u044C HR", uz: "HR\u2019ning shaxsiy profili" },
    "li.notConnected": { en: "Not connected", ru: "\u041D\u0435 \u043F\u043E\u0434\u043A\u043B\u044E\u0447\u0451\u043D", uz: "Ulanmagan" },
    "li.connect": { en: "Connect LinkedIn", ru: "\u041F\u043E\u0434\u043A\u043B\u044E\u0447\u0438\u0442\u044C LinkedIn", uz: "LinkedIn\u2019ni ulash" },
    "li.connectUnavailable": { en: "LinkedIn sign-in is not active yet. When available, you will approve access on LinkedIn; Talentio will not ask for your LinkedIn password.", ru: "\u0412\u0445\u043E\u0434 \u0447\u0435\u0440\u0435\u0437 LinkedIn \u043F\u043E\u043A\u0430 \u043D\u0435\u0434\u043E\u0441\u0442\u0443\u043F\u0435\u043D. \u041A\u043E\u0433\u0434\u0430 \u043E\u043D \u043F\u043E\u044F\u0432\u0438\u0442\u0441\u044F, \u0432\u044B \u043F\u043E\u0434\u0442\u0432\u0435\u0440\u0434\u0438\u0442\u0435 \u0434\u043E\u0441\u0442\u0443\u043F \u043D\u0430 LinkedIn; Talentio \u043D\u0435 \u0431\u0443\u0434\u0435\u0442 \u0437\u0430\u043F\u0440\u0430\u0448\u0438\u0432\u0430\u0442\u044C \u0432\u0430\u0448 \u043F\u0430\u0440\u043E\u043B\u044C.", uz: "LinkedIn orqali kirish hali ishlamaydi. U tayyor bo\u2018lganda ruxsatni LinkedIn\u2019da tasdiqlaysiz; Talentio LinkedIn parolingizni so\u2018ramaydi." },
    "li.howItWorksTitle": { en: "What this connection will do", ru: "\u0427\u0442\u043E \u0434\u0430\u0441\u0442 \u043F\u043E\u0434\u043A\u043B\u044E\u0447\u0435\u043D\u0438\u0435", uz: "Ulanish nima beradi" },
    "li.consentInfo": { en: "You sign in to LinkedIn and approve sharing from your own profile.", ru: "\u0412\u044B \u0432\u0445\u043E\u0434\u0438\u0442\u0435 \u0432 LinkedIn \u0438 \u0440\u0430\u0437\u0440\u0435\u0448\u0430\u0435\u0442\u0435 \u043F\u0443\u0431\u043B\u0438\u043A\u0430\u0446\u0438\u044E \u043E\u0442 \u0441\u0432\u043E\u0435\u0433\u043E \u0438\u043C\u0435\u043D\u0438.", uz: "LinkedIn\u2019ga o\u2018zingiz kirasiz va profilingizdan ulashishga ruxsat berasiz." },
    "li.feedOnly": { en: "This creates a regular post in your personal LinkedIn feed. It does not create a LinkedIn Jobs listing or post to a Company Page.", ru: "\u042D\u0442\u043E \u043E\u0431\u044B\u0447\u043D\u0430\u044F \u043F\u0443\u0431\u043B\u0438\u043A\u0430\u0446\u0438\u044F \u0432 \u043B\u0438\u0447\u043D\u043E\u0439 \u043B\u0435\u043D\u0442\u0435 LinkedIn. \u041E\u043D\u0430 \u043D\u0435 \u0441\u043E\u0437\u0434\u0430\u0451\u0442 \u0432\u0430\u043A\u0430\u043D\u0441\u0438\u044E \u0432 LinkedIn Jobs \u0438 \u043D\u0435 \u043F\u0443\u0431\u043B\u0438\u043A\u0443\u0435\u0442\u0441\u044F \u043D\u0430 \u0441\u0442\u0440\u0430\u043D\u0438\u0446\u0435 \u043A\u043E\u043C\u043F\u0430\u043D\u0438\u0438.", uz: "Bu shaxsiy LinkedIn lentangizda oddiy post yaratadi. LinkedIn Jobs\u2019da vakansiya ochmaydi va kompaniya sahifasiga joylamaydi." },
    "li.previewBeforeShare": { en: "You will review the poster, caption, and application link before sharing.", ru: "\u041F\u0435\u0440\u0435\u0434 \u043F\u0443\u0431\u043B\u0438\u043A\u0430\u0446\u0438\u0435\u0439 \u0432\u044B \u043F\u0440\u043E\u0432\u0435\u0440\u0438\u0442\u0435 \u043F\u043E\u0441\u0442\u0435\u0440, \u043F\u043E\u0434\u043F\u0438\u0441\u044C \u0438 \u0441\u0441\u044B\u043B\u043A\u0443 \u043D\u0430 \u043E\u0442\u043A\u043B\u0438\u043A.", uz: "Ulashishdan oldin poster, matn va ariza havolasini ko\u2018rib chiqasiz." },
    "li.shareTitle": { en: "Share on LinkedIn", ru: "\u041F\u043E\u0434\u0435\u043B\u0438\u0442\u044C\u0441\u044F \u0432 LinkedIn", uz: "LinkedIn\u2019da ulashish" },
    "li.shareCheckbox": { en: "Share this job to my LinkedIn feed", ru: "\u041F\u043E\u0434\u0435\u043B\u0438\u0442\u044C\u0441\u044F \u0432\u0430\u043A\u0430\u043D\u0441\u0438\u0435\u0439 \u0432 \u043C\u043E\u0435\u0439 \u043B\u0435\u043D\u0442\u0435 LinkedIn", uz: "Bu vakansiyani LinkedIn lentamda ulashish" },
    "li.connectBeforeShare": { en: "Connect your personal profile in Settings to enable sharing.", ru: "\u041F\u043E\u0434\u043A\u043B\u044E\u0447\u0438\u0442\u0435 \u043B\u0438\u0447\u043D\u044B\u0439 \u043F\u0440\u043E\u0444\u0438\u043B\u044C \u0432 \u043D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0430\u0445, \u0447\u0442\u043E\u0431\u044B \u0432\u043A\u043B\u044E\u0447\u0438\u0442\u044C \u043F\u0443\u0431\u043B\u0438\u043A\u0430\u0446\u0438\u044E.", uz: "Ulashishni yoqish uchun Sozlamalarda shaxsiy profilingizni ulang." },
    "li.openSettings": { en: "Open LinkedIn settings", ru: "\u041E\u0442\u043A\u0440\u044B\u0442\u044C \u043D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0438 LinkedIn", uz: "LinkedIn sozlamalarini ochish" },
    "li.previewTitle": { en: "Post preview", ru: "\u041F\u0440\u0435\u0434\u043F\u0440\u043E\u0441\u043C\u043E\u0442\u0440 \u043F\u0443\u0431\u043B\u0438\u043A\u0430\u0446\u0438\u0438", uz: "Postni oldindan ko\u2018rish" },
    "li.posterPreview": { en: "Job poster preview", ru: "\u041F\u0440\u0435\u0434\u043F\u0440\u043E\u0441\u043C\u043E\u0442\u0440 \u043F\u043E\u0441\u0442\u0435\u0440\u0430 \u0432\u0430\u043A\u0430\u043D\u0441\u0438\u0438", uz: "Vakansiya posterini oldindan ko\u2018rish" },
    "li.posterKicker": { en: "We\u2019re hiring", ru: "\u041C\u044B \u043D\u0430\u043D\u0438\u043C\u0430\u0435\u043C", uz: "Ishga taklif qilamiz" },
    "li.posterCta": { en: "View job and apply", ru: "\u0421\u043C\u043E\u0442\u0440\u0435\u0442\u044C \u0432\u0430\u043A\u0430\u043D\u0441\u0438\u044E", uz: "Vakansiyani ko\u2018rish" },
    "li.captionLabel": { en: "Caption", ru: "\u0422\u0435\u043A\u0441\u0442 \u043F\u0443\u0431\u043B\u0438\u043A\u0430\u0446\u0438\u0438", uz: "Post matni" },
